using System;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class LauncherFooterVisualTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{true,false})using(var f=new ManagerHub()){f.SetTheme(dark,false);f.Show();for(int i=0;i<15;i++)Application.DoEvents();var controls=Walk(f).ToArray();var b=new[]{controls.OfType<Button>().Single(x=>x.Text=="ⓘ"),controls.OfType<Button>().Single(x=>x.Text=="Инструкция"),controls.OfType<Button>().Single(x=>x.Text=="Скачать комплект"),controls.OfType<Button>().Single(x=>x.Text=="Закрыть программу")};foreach(var button in b)for(Control parent=button.Parent;parent!=null;parent=parent.Parent){var visible=parent.RectangleToClient(button.RectangleToScreen(button.ClientRectangle));if(!parent.ClientRectangle.Contains(visible))throw new Exception("Launcher footer clipped by "+parent.GetType().Name+": "+button.Text);n++;}if(b[0].Width!=b[0].Height)throw new Exception("Info not square");n++;if(b.Skip(1).Select(x=>x.Size).Distinct().Count()!=1)throw new Exception("Unequal action sizes");n++;int[] gaps=Enumerable.Range(0,3).Select(i=>b[i+1].PointToScreen(Point.Empty).X-b[i].PointToScreen(new Point(b[i].Width,0)).X).ToArray();if(gaps.Max()-gaps.Min()>1||gaps.Max()>b[0].Height/2)throw new Exception("Uneven or oversized gaps: "+String.Join(",",gaps));n++;foreach(int width in new[]{870,1000,1120,1260}){f.ClientSize=new Size(width,f.ClientSize.Height);Application.DoEvents();var cards=Walk(f).OfType<Card>().Select(card=>card.RectangleToScreen(card.ClientRectangle)).ToArray();var left=b[0].RectangleToScreen(b[0].ClientRectangle).Left;var right=b[3].RectangleToScreen(b[3].ClientRectangle).Right;if(Math.Abs(cards.Min(card=>card.Left)-left)>1||Math.Abs(cards.Max(card=>card.Right)-right)>1)throw new Exception("Footer edges do not match cards at "+width+": "+left+" / "+right);n++;}using(var image=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(image,new Rectangle(Point.Empty,image.Size));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"launcher-fixed-"+dark+".png"));}}Console.WriteLine("PASS: "+n+" launcher square/equal buttons/compact equal gap checks, both themes.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}